def test_desktop_equality_b181():
    bad = [(hex(a), hex(b), eq) for a, b, eq in B181 if collation.equal(chr(a), chr(b)) != bool(eq)]
    assert not bad, bad[:20]


def test_desktop_equality_and_order_b185():
    bad = []
    for a, b, eq, lt in B185:
        ka, kb = collation.sort_key(chr(a)), collation.sort_key(chr(b))
        if (ka == kb) != bool(eq) or (ka < kb) != bool(lt):
            bad.append((hex(a), hex(b), eq, lt))
    assert not bad, bad[:20]


def test_desktop_neighbours_b187():
    bad = [(hex(a), hex(b), eq) for a, b, eq in B187
           if (collation.sort_key(chr(a)) == collation.sort_key(chr(b))) != bool(eq)]
    assert not bad, bad[:20]


def test_desktop_order_b186():
    """Desktop's order of every BMP character, sampled: the collation, then
    the code point for characters it finds equal."""
    got = sorted(ORDER186, key=lambda cp: (collation.sort_key(chr(cp)), cp))
    assert got == ORDER186


def test_marks_b189():
    """Nonspacing marks: a decomposed letter equals the precomposed one,
    several marks add up in any order, a mark after an ignorable still
    counts. Equality only: Desktop orders some of these texts by where each
    one ends ("é" < "e-" while "e" + U+0301 > "e-"), which is no
    consistent order for a key to follow."""
    bad = [(T189[i], T189[j], "=" if eq else "<>") for i, j, eq, _lt in B189
           if (collation.sort_key(T189[i]) == collation.sort_key(T189[j])) != bool(eq)]
    assert not bad, bad[:20]


@pytest.mark.parametrize("a,b", [
    ("K", "\u212a"), ("\u03a9", "\u2126"), ("\u05db", "\u05da"), ("\u3042", "\u3041"), ("\u1100", "\u11a8"),
    ("\u0191", "\u0192"), ("\u015e", "\u1e64"), ("\u246a", "\u24eb"), ("\u0f4a", "\u0f4f"), ("\u05d0", "\u2135"),
])
def test_kept_apart(a, b):
    assert not collation.equal(a, b)


@pytest.mark.parametrize("a,b", [
    ("a", "A"), ("2", "\u00b2"), ("A", "\u1d00"), ("1", "\u2460"), ("0", "\u2080"), ("A", "\uff21"),
    ("\u3042", "\u30a2"), ("\u00e6", "ae"), ("\u00df", "ss"), ("\u00e9", "e\u0301"), ("\u1ebf", "e\u0302\u0301"),
])
def test_equal(a, b):
    assert collation.equal(a, b)
